    async def watch_tickers(self, symbols: Strings = None, params={}) -> Tickers:
        """

        https://docs.nado.xyz/developer-resources/api/subscriptions/streams

        watches price tickers with the best bid and ask for all markets of a specific list
        :param str[] [symbols]: unified symbols of the markets to fetch the ticker for
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a dictionary of `ticker structures <https://docs.ccxt.com/#/?id=ticker-structure>`
        """
        await self.load_markets()
        symbols = self.market_symbols(symbols, None, True, True, True)
        market = None
        messageHash = 'ticker'
        streamType = 'all_bbo'
        if symbols is not None:
            symbolsLength = len(symbols)
            if symbolsLength == 1:
                market = self.market(symbols[0])
                messageHash = 'ticker:' + market['symbol']
                streamType = 'best_bid_offer'
        ticker = await self.watch_public(streamType, market, messageHash, params)
        if self.newUpdates:
            if messageHash == 'ticker':
                return self.filter_by_array(ticker, 'symbol', symbols)
            tickers = {}
            tickers[ticker['symbol']] = ticker
            return tickers
        return self.filter_by_array(self.tickers, 'symbol', symbols)

