        trigger = self.safe_bool_2(params, 'stop', 'trigger')
        if trigger:
            raise NotSupported(self.id + ' cancelAllOrdersWs() does not support trigger orders, use cancelAllOrders() instead')
        params = self.extend({'id': self.request_id()}, params)
