    async def watch_execute_request(self, requestId: str, request):
        # the v2 gateway dispatches requests concurrently, so responses arrive
        # in completion order, not send order — every execute carries a unique
        # request id and its response is correlated by the echoed id
        url = self.urls['api']['ws']['gateway']
        messageHash = 'execute:' + requestId
        return await self.watch(url, messageHash, request, messageHash)

    async def watch_public(self, streamType, market, messageHash: str, params={}):
        url = self.urls['api']['ws']['subscriptions']
        stream = {
            'type': streamType,
        }
        if market is not None:
            stream['product_id'] = self.parse_to_int(market['id'])
        request = {
            'method': 'subscribe',
            'stream': self.deep_extend(stream, params),
            'id': self.request_id(),
        }
        subscribeHash = 'subscribe:' + self.json(request['stream'])
        subscription = {
            'streamType': streamType,
            'symbol': self.safe_string(market, 'symbol'),
        }
        client = self.client(url)
        clientSubscription = self.safe_value(client.subscriptions, subscribeHash)
        if clientSubscription is None:
            id = self.safe_string(request, 'id')
            client.subscriptions['subscription:' + id] = {
                'subscribeHash': subscribeHash,
            }
            self.watch_multiple(url, [subscribeHash], request, [subscribeHash], subscription)
        return await self.watch(url, messageHash)

    async def watch_private(self, streamType, stream, messageHash: str, params={}):
        url = self.urls['api']['ws']['subscriptions']
        client = self.client(url)
        clientSubscription = self.safe_value(client.subscriptions, messageHash)
        if clientSubscription is not None:
            return await self.watch(url, messageHash)
        id = self.request_id()
        subscribeHash = 'subscribe:' + messageHash
        request = {
            'method': 'subscribe',
            'stream': self.deep_extend(stream, params),
            'id': id,
        }
        subscription = {
            'streamType': streamType,
        }
        client.subscriptions['subscription:' + self.number_to_string(id)] = {
            'subscribeHash': subscribeHash,
        }
        self.watch_multiple(url, [subscribeHash], request, [messageHash], subscription)
        return await self.watch(url, messageHash)

    async def un_watch_private(self, stream, messageHash: str, params={}):
        url = self.urls['api']['ws']['subscriptions']
        id = self.request_id()
        unsubscribeHash = 'unsubscribe:' + messageHash
        request = {
            'method': 'unsubscribe',
            'stream': self.deep_extend(stream, params),
            'id': id,
        }
        subscription = {
            'id': id,
            'messageHash': messageHash,
        }
        client = self.client(url)
        client.subscriptions['unsubscription:' + self.number_to_string(id)] = {
            'messageHash': messageHash,
            'unsubscribeHash': unsubscribeHash,
        }
        return await self.watch(url, unsubscribeHash, request, unsubscribeHash, subscription)

    async def authenticate(self, params={}):
        self.check_required_credentials()
        url = self.urls['api']['ws']['subscriptions']
        client = self.client(url)
        messageHash = 'authenticated'
        authenticated = self.safe_value(client.subscriptions, messageHash)
        if authenticated is not None:
            future = self.safe_value(client.futures, messageHash)
            if future is not None:
                return await future
            return authenticated
        recvWindow = None
        recvWindow, params = self.handle_option_and_params(params, 'authenticate', 'recvWindow', 5000)
        subaccount = None
        subaccount, params = self.handle_option_and_params(params, 'authenticate', 'subaccount', 'default')
        id = self.request_id()
        sender = self.create_subaccount(self.walletAddress, subaccount)
        expiration = self.sum(self.milliseconds(), recvWindow)
        tx = {
            'sender': sender,
            'expiration': self.number_to_string(expiration),
        }
        contracts = await self.queryContracts()
        chainId = self.safe_string(contracts, 'chain_id')
        endpointAddress = self.safe_string(contracts, 'endpoint_addr')
        if endpointAddress is None:
            raise ExchangeError(self.id + ' authenticate() requires endpoint_addr from contracts query')
        signature = self.sign_stream_authentication(tx, chainId, endpointAddress)
        request = {
            'method': 'authenticate',
            'id': id,
            'tx': tx,
            'signature': signature,
        }
        client.subscriptions['authentication:' + self.number_to_string(id)] = messageHash
        return await self.watch(url, messageHash, self.extend(request, params), messageHash)

    def sign_stream_authentication(self, tx, chainId, endpointAddress: str):
        domain = {
            'name': 'Nado',
            'version': '0.0.1',
            'chainId': chainId,
            'verifyingContract': endpointAddress,
        }
        messageTypes = {
            'StreamAuthentication': [
                {'name': 'sender', 'type': 'bytes32'},
                {'name': 'expiration', 'type': 'uint64'},
            ],
        }
        encoded = self.eth_encode_structured_data(domain, messageTypes, tx)
        hash = '0x' + self.hash(encoded, 'keccak', 'hex')
        return self.signHash(hash, self.privateKey)

    def create_public_subscription_request(self, method: str, streamType, market=None, id: Int = None, params={}):
        stream = {
            'type': streamType,
        }
        if market is not None:
            stream['product_id'] = self.parse_to_int(market['id'])
        return {
            'method': method,
            'stream': self.deep_extend(stream, params),
            'id': id,
        }

    async def watch_public_multiple(self, streamType, markets, messageHashes: List[str], params={}, subscriptionParams=None):
        url = self.urls['api']['ws']['subscriptions']
        client = self.client(url)
        for i in range(0, len(messageHashes)):
            messageHash = messageHashes[i]
            clientSubscription = self.safe_value(client.subscriptions, messageHash)
            if clientSubscription is None:
                market = markets[i]
                id = self.request_id()
                requestParams = params if (subscriptionParams is None) else subscriptionParams[i]
                request = self.create_public_subscription_request('subscribe', streamType, market, id, requestParams)
                subscribeHash = 'subscribe:' + self.json(request['stream'])
                streamSubscription = self.safe_value(client.subscriptions, subscribeHash)
                if streamSubscription is None:
                    subscription = {
                        'streamType': streamType,
                        'symbol': self.safe_string(market, 'symbol'),
                    }
                    client.subscriptions['subscription:' + self.number_to_string(id)] = {
                        'subscribeHash': subscribeHash,
                    }
                    self.watch_multiple(url, [subscribeHash], request, [subscribeHash], subscription)
        return await self.watch_multiple(url, messageHashes, None, messageHashes)

    async def un_watch_public(self, streamType, market, messageHash: str, params={}):
        url = self.urls['api']['ws']['subscriptions']
        id = self.request_id()
        request = self.create_public_subscription_request('unsubscribe', streamType, market, id, params)
        subscription = {
            'id': id,
            'messageHash': messageHash,
        }
        unsubscribeHash = 'unsubscribe:' + messageHash
        client = self.client(url)
        client.subscriptions['unsubscription:' + self.number_to_string(id)] = {
            'messageHash': messageHash,
            'unsubscribeHash': unsubscribeHash,
        }
        return await self.watch(url, unsubscribeHash, request, unsubscribeHash, subscription)

    async def un_watch_public_multiple(self, streamType, markets, messageHashes: List[str], params={}, subscriptionParams=None):
        url = self.urls['api']['ws']['subscriptions']
        client = self.client(url)
        results = []
        for i in range(0, len(messageHashes)):
            messageHash = messageHashes[i]
            id = self.request_id()
            unsubscribeHash = 'unsubscribe:' + messageHash
            requestParams = params if (subscriptionParams is None) else subscriptionParams[i]
            request = self.create_public_subscription_request('unsubscribe', streamType, markets[i], id, requestParams)
            subscription = {
                'id': id,
                'messageHash': messageHash,
            }
            client.subscriptions['unsubscription:' + self.number_to_string(id)] = {
                'messageHash': messageHash,
                'unsubscribeHash': unsubscribeHash,
            }
            results.append(await self.watch_multiple(url, [unsubscribeHash], request, [unsubscribeHash], subscription))
        return results

    def parse_ws_timestamp(self, message: dict, key: str) -> Int:
        value = self.safe_string(message, key)
        if value is None:
            return None
        length = len(value)
        if length > 13:
            return self.parse_to_int(value[0:length - 6])
        return self.safe_integer(message, key)

    def parse_ws_trade(self, trade: dict, market=None) -> Trade:
        #
        #     {
        #         "type": "trade",
        #         "timestamp": "1676151190656903000",
        #         "product_id": 1,
        #         "price": "25000000000000000000000",
        #         "taker_qty": "1000000000000000000",
        #         "maker_qty": "1000000000000000000",
        #         "is_taker_buyer": True
        #     }
        #
        marketId = self.safe_string(trade, 'product_id')
        market = self.safe_market(marketId, market)
        timestamp = self.parse_ws_timestamp(trade, 'timestamp')
        isTakerBuyer = self.safe_bool(trade, 'is_taker_buyer')
        side = None
        if isTakerBuyer is not None:
            side = 'buy' if isTakerBuyer else 'sell'
        return self.safe_trade({
            'info': trade,
            'id': None,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'symbol': market['symbol'],
            'order': None,
            'type': None,
            'side': side,
            'takerOrMaker': 'taker',
            'price': self.parseX18(self.safe_string(trade, 'price')),
            'amount': self.parseX18(self.safe_string(trade, 'taker_qty')),
            'cost': None,
            'fee': None,
        }, market)

    def parse_ws_my_trade(self, trade: dict, market=None) -> Trade:
        #
        #     {
        #         "type": "fill",
        #         "timestamp": "1695081920633151000",
        #         "product_id": 1,
        #         "subaccount": "0x...",
        #         "order_digest": "0x...",
        #         "appendix": "1",
        #         "filled_qty": "18000000000000000",
        #         "remaining_qty": "82000000000000000",
        #         "original_qty": "100000000000000000",
        #         "price": "25000000000000000000000",
        #         "is_taker": True,
        #         "is_bid": True,
        #         "fee": "4500000000000000",
        #         "submission_idx": 1,
        #         "id": 100
        #     }
        #
        marketId = self.safe_string(trade, 'product_id')
        market = self.safe_market(marketId, market)
        timestamp = self.parse_ws_timestamp(trade, 'timestamp')
        isBid = self.safe_bool(trade, 'is_bid')
        side = None
        if isBid is not None:
            side = 'buy' if isBid else 'sell'
        isTaker = self.safe_bool(trade, 'is_taker')
        takerOrMaker = None
        if isTaker is not None:
            takerOrMaker = 'taker' if isTaker else 'maker'
        feeCost = self.parseX18(self.safe_string(trade, 'fee'))
        fee = None
        if feeCost is not None:
            fee = {
                'cost': feeCost,
                'currency': market['quote'],
            }
        return self.safe_trade({
            'info': trade,
            # the id is required: myTrades are cached by id, and fills with an None id
            # would overwrite each other in the cache, collapsing the history to the last fill
            'id': self.safe_string_2(trade, 'id', 'submission_idx'),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'symbol': market['symbol'],
            'order': self.safe_string(trade, 'order_digest'),
            'type': None,
            'side': side,
            'takerOrMaker': takerOrMaker,
            'price': self.parseX18(self.safe_string(trade, 'price')),
            'amount': self.parseX18(self.safe_string(trade, 'filled_qty')),
            'cost': None,
            'fee': fee,
        }, market)

    def handle_trade(self, client: Client, message):
        marketId = self.safe_string(message, 'product_id')
        market = self.safe_market(marketId)
        symbol = market['symbol']
        messageHash = 'trade:' + symbol
        trades = self.safe_value(self.trades, symbol)
        if trades is None:
            limit = self.safe_integer(self.options, 'tradesLimit', 1000)
            trades = ArrayCache(limit)
            self.trades[symbol] = trades
        trade = self.parse_ws_trade(message, market)
        trades.append(trade)
        client.resolve(trades, messageHash)

    def handle_my_trade(self, client: Client, message):
        trade = self.parse_ws_my_trade(message)
        if self.myTrades is None:
            limit = self.safe_integer(self.options, 'tradesLimit', 1000)
            self.myTrades = ArrayCacheBySymbolById(limit)
        trades = self.myTrades
        trades.append(trade)
        symbol = trade['symbol']
        client.resolve(trades, 'myTrades')
        client.resolve(trades, 'myTrades:' + symbol)

    def handle_ohlcv(self, client: Client, message):
        #
        #     {
        #         "type": "latest_candlestick",
        #         "timestamp": "1782179760",
        #         "product_id": 2,
        #         "granularity": 60,
        #         "open_x18": "64148000000000000000000",
        #         "high_x18": "64148000000000000000000",
        #         "low_x18": "64148000000000000000000",
        #         "close_x18": "64148000000000000000000",
        #         "volume": "24250000000000000"
        #     }
        #
        marketId = self.safe_string(message, 'product_id')
        market = self.safe_market(marketId)
        symbol = market['symbol']
        granularity = self.safe_integer(message, 'granularity')
        timeframe = self.find_timeframe(granularity)
        if not (symbol in self.ohlcvs):
            self.ohlcvs[symbol] = {}
        stored = self.safe_value(self.ohlcvs[symbol], timeframe)
        if stored is None:
            limit = self.safe_integer(self.options, 'OHLCVLimit', 1000)
            stored = ArrayCacheByTimestamp(limit)
            self.ohlcvs[symbol][timeframe] = stored
        parsed = self.parse_ohlcv(message, market)
        stored.append(parsed)
        messageHash = 'ohlcv:' + timeframe + ':' + symbol
        client.resolve([symbol, timeframe, stored], messageHash)

    def parse_ws_order(self, order: dict, market=None) -> Order:
        #
        #     {
        #         "type": "order_update",
        #         "timestamp": "1695081920633151000",
        #         "product_id": 1,
        #         "digest": "0xf7712b63ccf70358db8f201e9bf33977423e7a63f6a16f6dab180bdd580f7c6c",
        #         "amount": "82000000000000000",
        #         "reason": "filled",
        #         "filled_qty": "18000000000000000",
        #         "filled_price": "25000000000000000000000",
        #         "id": 100
        #     }
        #
        marketId = self.safe_string(order, 'product_id')
        market = self.safe_market(marketId, market)
        timestamp = self.parse_ws_timestamp(order, 'timestamp')
        id = self.safe_string(order, 'digest')
        amountString = self.safe_string(order, 'amount')
        remaining = None
        if amountString is not None:
            remaining = self.parseX18(amountString)
        filled = self.parseX18(self.safe_string(order, 'filled_qty'))
        average = self.parseX18(self.safe_string(order, 'filled_price'))
        reason = self.safe_string(order, 'reason')
        status = None
        if reason == 'placed':
            status = 'open'
        elif reason == 'filled':
            status = 'open'
            if (amountString is not None) and Precise.string_eq(amountString, '0'):
                status = 'closed'
        elif reason == 'cancelled':
            status = 'canceled'
        return self.safe_order({
            'info': order,
            'id': id,
            'clientOrderId': None,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'lastTradeTimestamp': None if (filled is None) else timestamp,
            'lastUpdateTimestamp': timestamp,
            'symbol': market['symbol'],
            'type': None,
            'timeInForce': None,
            'postOnly': None,
            'side': None,
            'price': None,
            'stopPrice': None,
            'triggerPrice': None,
            'amount': None,
            'cost': None,
            'average': average,
            'filled': filled,
            'remaining': remaining,
            'status': status,
            'fee': None,
            'trades': None,
        }, market)

    def handle_order(self, client: Client, message):
        order = self.parse_ws_order(message)
        if self.orders is None:
            limit = self.safe_integer(self.options, 'ordersLimit', 1000)
            self.orders = ArrayCacheBySymbolById(limit)
        orders = self.orders
        orders.append(order)
        symbol = order['symbol']
        client.resolve(orders, 'orders')
        client.resolve(orders, 'orders:' + symbol)

    def parse_ws_position(self, position: dict, market=None) -> Position:
        #
        #     {
        #         "type": "position_change",
        #         "timestamp": "1695081920633151000",
        #         "product_id": 2,
        #         "subaccount": "0x15f43d1f2dee81424afd891943262aa90f22cc2a64656661756c740000000000",
        #         "isolated": False,
        #         "amount": "100000000000000000",
        #         "v_quote_amount": "-3033500000000000000000",
        #         "reason": "match_orders"
        #     }
        #
        marketId = self.safe_string(position, 'product_id')
        market = self.safe_market(marketId, market)
        timestamp = self.parse_ws_timestamp(position, 'timestamp')
        amountString = self.safe_string(position, 'amount')
        vQuoteAmount = self.safe_string(position, 'v_quote_amount')
        side = None
        contracts = None
        entryPrice = None
        if amountString is not None:
            if Precise.string_gt(amountString, '0'):
                side = 'long'
            elif Precise.string_lt(amountString, '0'):
                side = 'short'
            absoluteAmount = Precise.string_abs(amountString)
            contracts = self.parseX18(absoluteAmount)
            if (vQuoteAmount is not None) and not Precise.string_equals(absoluteAmount, '0'):
                entryPrice = self.parse_number(Precise.string_div(Precise.string_abs(vQuoteAmount), absoluteAmount))
        return self.safe_position({
            'info': position,
            'id': None,
            'symbol': market['symbol'],
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'isolated': self.safe_bool(position, 'isolated'),
            'hedged': False,
            'side': side,
            'contracts': contracts,
            'contractSize': self.safe_number(market, 'contractSize'),
            'entryPrice': entryPrice,
            'markPrice': None,
            'notional': None,
            'leverage': None,
            'collateral': None,
            'initialMargin': None,
            'initialMarginPercentage': None,
            'maintenanceMargin': None,
            'maintenanceMarginPercentage': None,
            'unrealizedPnl': None,
            'liquidationPrice': None,
            'marginMode': None,
            'marginRatio': None,
            'percentage': None,
        })

    def handle_position(self, client: Client, message):
        marketId = self.safe_string(message, 'product_id')
        market = self.safe_market(marketId)
        if not self.safe_bool(market, 'contract', False):
            return
        position = self.parse_ws_position(message, market)
        if self.positions is None:
            self.positions = ArrayCacheBySymbolBySide()
        positions = self.positions
        side = self.safe_string(position, 'side')
        if side is None:
            longPosition = self.extend({}, position)
            longPosition['side'] = 'long'
            positions.append(longPosition)
            shortPosition = self.extend({}, position)
            shortPosition['side'] = 'short'
            positions.append(shortPosition)
        else:
            positions.append(position)
        symbol = position['symbol']
        client.resolve(positions, 'positions')
        client.resolve(positions, 'positions:' + symbol)

    def parse_ws_bid_ask(self, bidask: dict, market=None) -> Ticker:
        #
        #     {
        #         "type": "best_bid_offer",
        #         "timestamp": "1676151190656903000",
        #         "product_id": 1,
        #         "bid_price": "24990000000000000000000",
        #         "bid_qty": "5000000000000000000",
        #         "ask_price": "25010000000000000000000",
        #         "ask_qty": "3000000000000000000"
        #     }
        #
        marketId = self.safe_string(bidask, 'product_id')
        market = self.safe_market(marketId, market)
        timestamp = self.parse_ws_timestamp(bidask, 'timestamp')
        return self.safe_ticker({
            'symbol': market['symbol'],
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'ask': self.parseX18(self.safe_string(bidask, 'ask_price')),
            'askVolume': self.parseX18(self.safe_string(bidask, 'ask_qty')),
            'bid': self.parseX18(self.safe_string(bidask, 'bid_price')),
            'bidVolume': self.parseX18(self.safe_string(bidask, 'bid_qty')),
            'info': bidask,
        }, market)

    def handle_bid_ask(self, client: Client, message):
        ticker = self.parse_ws_bid_ask(message)
        symbol = ticker['symbol']
        self.bidsasks[symbol] = ticker
        self.tickers[symbol] = ticker
        tickers = {}
        tickers[symbol] = ticker
        client.resolve(ticker, 'bidask:' + symbol)
        client.resolve(ticker, 'ticker:' + symbol)
        client.resolve(tickers, 'bidask')
        client.resolve(tickers, 'ticker')

    def parse_ws_all_bids_asks(self, message: dict) -> Tickers:
        #
        #     {
        #         "type": "all_bbo",
        #         "time": "1781750134714",
        #         "bbos": {
        #             "2": {"bid": "64924000000000000000000", "ask": "64935000000000000000000"}
        #         }
        #     }
        #
        timestamp = self.safe_integer(message, 'time')
        bbos = self.safe_dict(message, 'bbos', {})
        marketIds = list(bbos.keys())
        result = {}
        for i in range(0, len(marketIds)):
            marketId = marketIds[i]
            market = self.safe_market(marketId)
            bbo = self.safe_dict(bbos, marketId, {})
            bid = self.safe_string(bbo, 'bid')
            ask = self.safe_string(bbo, 'ask')
            maxPrice = '170141183460469231731687303715884105727'
            if Precise.string_gt(bid, '0') and Precise.string_gt(ask, '0') and not Precise.string_equals(bid, maxPrice) and not Precise.string_equals(ask, maxPrice):
                ticker = self.safe_ticker({
                    'symbol': market['symbol'],
                    'timestamp': timestamp,
                    'datetime': self.iso8601(timestamp),
                    'ask': self.parseX18(ask),
                    'bid': self.parseX18(bid),
                    'info': bbo,
                }, market)
                symbol = market['symbol']
                result[symbol] = ticker
        return result

    def handle_all_bids_asks(self, client: Client, message):
        tickers = self.parse_ws_all_bids_asks(message)
        symbols = list(tickers.keys())
        for i in range(0, len(symbols)):
            symbol = symbols[i]
            ticker = tickers[symbol]
            self.bidsasks[symbol] = ticker
            self.tickers[symbol] = ticker
            client.resolve(ticker, 'bidask:' + symbol)
            client.resolve(ticker, 'ticker:' + symbol)
        client.resolve(tickers, 'bidask')
        client.resolve(tickers, 'ticker')

    def handle_delta(self, bookside, delta):
        bidAsk = [
            self.parseX18(self.safe_string(delta, 0)),
            self.parseX18(self.safe_string(delta, 1)),
        ]
        bookside.storeArray(bidAsk)

    def handle_order_book(self, client: Client, message):
        #
        #     {
        #         "type": "book_depth",
        #         "min_timestamp": "1683805381879572835",
        #         "max_timestamp": "1683805381879572835",
        #         "last_max_timestamp": "1683805381771464799",
        #         "product_id": 1,
        #         "bids": [["21594490000000000000000", "51007390115411548"]],
        #         "asks": [["21694490000000000000000", "0"]]
        #     }
        #
        marketId = self.safe_string(message, 'product_id')
        market = self.safe_market(marketId)
        symbol = market['symbol']
        if not (symbol in self.orderbooks):
            self.orderbooks[symbol] = self.order_book()
        orderbook = self.orderbooks[symbol]
        asks = self.safe_list(message, 'asks', [])
        bids = self.safe_list(message, 'bids', [])
        self.handle_deltas(orderbook['asks'], asks)
        self.handle_deltas(orderbook['bids'], bids)
        timestamp = self.parse_ws_timestamp(message, 'max_timestamp')
        orderbook['symbol'] = symbol
        orderbook['timestamp'] = timestamp
        orderbook['datetime'] = self.iso8601(timestamp)
        orderbook['maxTimestamp'] = self.safe_string(message, 'max_timestamp')
        messageHash = 'orderbook:' + symbol
        client.resolve(orderbook, messageHash)

    def handle_execute_response(self, client: Client, message):
        #
        #     {
        #         "status": "success",
        #         "signature": "0x...",
        #         "data": {
        #             "digest": "0x..."
        #         },
        #         "request_type": "execute_place_order",
        #         "id": 100
        #     }
        #
        id = self.safe_string(message, 'id')
        if id is None:
            return
        messageHash = 'execute:' + id
        subscription = self.safe_value(client.subscriptions, messageHash)
        if subscription is not None:
            del client.subscriptions[messageHash]
        client.resolve(message, messageHash)

    def handle_subscription(self, client: Client, message):
        id = self.safe_string(message, 'id')
        subscription = self.safe_dict(client.subscriptions, 'subscription:' + id)
        if subscription is not None:
            subscribeHash = self.safe_string(subscription, 'subscribeHash')
            del client.subscriptions['subscription:' + id]
            client.resolve(message, subscribeHash)

    def handle_authentication(self, client: Client, message):
        id = self.safe_string(message, 'id')
        messageHash = self.safe_string(client.subscriptions, 'authentication:' + id)
        if messageHash is not None:
            del client.subscriptions['authentication:' + id]
            client.subscriptions[messageHash] = True
            client.resolve(message, messageHash)

    def handle_unsubscription(self, client: Client, message):
        id = self.safe_string(message, 'id')
        unsubscription = self.safe_dict(client.subscriptions, 'unsubscription:' + id)
        if unsubscription is not None:
            messageHash = self.safe_string(unsubscription, 'messageHash')
            unsubscribeHash = self.safe_string(unsubscription, 'unsubscribeHash')
            del client.subscriptions['unsubscription:' + id]
            self.clean_unsubscription(client, messageHash, unsubscribeHash)
            self.handle_unsubscription_cache(messageHash)
            client.resolve(message, unsubscribeHash)
            return
        subscriptions = list(client.subscriptions.keys())
        for i in range(0, len(subscriptions)):
            unsubscribeHash = subscriptions[i]
            subscription = client.subscriptions[unsubscribeHash]
            subscriptionId = self.safe_string(subscription, 'id')
            if subscriptionId != id:
                continue
            messageHash = self.safe_string(subscription, 'messageHash')
            self.clean_unsubscription(client, messageHash, unsubscribeHash)
            self.handle_unsubscription_cache(messageHash)
            client.resolve(message, unsubscribeHash)
            return

    def handle_unsubscription_cache(self, messageHash: str):
        if messageHash.find('trade:') == 0:
            symbol = messageHash.replace('trade:', '')
            if symbol in self.trades:
                del self.trades[symbol]
        elif messageHash.find('orderbook:') == 0:
            symbol = messageHash.replace('orderbook:', '')
            if symbol in self.orderbooks:
                del self.orderbooks[symbol]
        elif messageHash.find('ohlcv:') == 0:
            parts = messageHash.split(':')
            timeframe = self.safe_string(parts, 1)
            symbol = self.safe_string(parts, 2)
            if (symbol in self.ohlcvs) and (timeframe in self.ohlcvs[symbol]):
                del self.ohlcvs[symbol][timeframe]
        elif messageHash.find('ticker:') == 0:
            symbol = messageHash.replace('ticker:', '')
            if symbol in self.tickers:
                del self.tickers[symbol]
        elif messageHash == 'ticker':
            symbols = list(self.tickers.keys())
            for i in range(0, len(symbols)):
                del self.tickers[symbols[i]]
        elif messageHash.find('bidask:') == 0:
            symbol = messageHash.replace('bidask:', '')
            if symbol in self.bidsasks:
                del self.bidsasks[symbol]
        elif messageHash == 'bidask':
            symbols = list(self.bidsasks.keys())
            for i in range(0, len(symbols)):
                del self.bidsasks[symbols[i]]
        elif messageHash.find('orders') == 0:
            self.orders = None
        elif messageHash.find('myTrades') == 0:
            self.myTrades = None
        elif messageHash.find('positions') == 0:
            self.positions = None

    def ping(self, client: Client):
        gatewayUrl = self.urls['api']['ws']['gateway']
        if client.url == gatewayUrl:
            # the v2 gateway is kept alive with protocol-level ping frames,
            # returning None makes the client send one instead of a message
            return None
        return {
            'method': 'ping',
            'id': self.request_id(),
            'client_time': self.number_to_string(self.milliseconds()),
        }

    def handle_pong(self, client: Client, message):
        #
        #     {
        #         "result": {
        #             "method": "pong",
        #             "server_time": "1780000000123",
        #             "client_time": "1780000000000"
        #         },
        #         "id": 10
        #     }
        #
        result = self.safe_dict(message, 'result', {})
        client.lastPong = self.safe_integer(result, 'server_time', self.milliseconds())
        return message

    def handle_error_message(self, client: Client, message) -> Bool:
        error = self.safe_value(message, 'error')
        status = self.safe_string(message, 'status')
        if (error is None) and (status != 'failure'):
            return False
        feedback = ExchangeError(self.id + ' ' + self.json(message))
        id = self.safe_string(message, 'id')
        if id is not None:
            executeHash = 'execute:' + id
            executeSubscription = self.safe_value(client.subscriptions, executeHash)
            if executeSubscription is not None:
                del client.subscriptions[executeHash]
                client.reject(feedback, executeHash)
                return True
        subscription = self.safe_dict(client.subscriptions, 'subscription:' + id)
        if subscription is not None:
            subscribeHash = self.safe_string(subscription, 'subscribeHash')
            del client.subscriptions['subscription:' + id]
            client.reject(feedback, subscribeHash)
        else:
            client.reject(feedback)
        return True

    def handle_message(self, client: Client, message):
        if self.handle_error_message(client, message):
            return
        id = self.safe_string(message, 'id')
        hasResult = ('result' in message)
        result = self.safe_value(message, 'result')
        method = self.safe_string(result, 'method')
        if method == 'pong':
            # pong replies carry both 'id' and 'result' so they must be routed
            # before the subscription-ack branch below swallows them
            self.handle_pong(client, message)
            return
        requestType = self.safe_string(message, 'request_type')
        if requestType is not None:
            # v2 gateway execute responses carry 'request_type' and the echoed request id
            self.handle_execute_response(client, message)
            return
        if (id is not None) and hasResult:
            authentication = self.safe_value(client.subscriptions, 'authentication:' + id)
            if authentication is not None:
                self.handle_authentication(client, message)
                return
            subscription = self.safe_value(client.subscriptions, 'subscription:' + id)
            if subscription is not None:
                self.handle_subscription(client, message)
                return
            if result is None:
                self.handle_unsubscription(client, message)
                return
            self.handle_subscription(client, message)
            return
        type = self.safe_string(message, 'type')
        methods = {
            'trade': self.handle_trade,
            'all_bbo': self.handle_all_bids_asks,
            'best_bid_offer': self.handle_bid_ask,
            'book_depth': self.handle_order_book,
            'fill': self.handle_my_trade,
            'latest_candlestick': self.handle_ohlcv,
            'order_update': self.handle_order,
            'position_change': self.handle_position,
        }
        handler = self.safe_value(methods, type)
        if handler is not None:
            handler(client, message)
